<template>
  <div>
    <input 
      v-model="query" 
      placeholder="Search..."
      @input="onSearch"
    />
    <ul>
      <li v-for="item in results" :key="item.id">{{ item.name }}</li>
    </ul>
  </div>
</template>

<script setup>
import { ref } from 'vue';

const query = ref('');
const results = ref([]);
let timeout;

const onSearch = () => {
  clearTimeout(timeout);
  timeout = setTimeout(() => {
    if (query.value.trim()) {
      fetch(`/api/search?q=${encodeURIComponent(query.value)}`)
        .then(res => res.json())
        .then(data => results.value = data);
    }
  }, 300);
};
</script>
